module.origin_ip.fix_snippet:
# ufw
sudo ufw default deny incoming
sudo ufw allow from 203.0.113.0/24 to any port 80,443 proto tcp
sudo ufw allow from 203.0.113.10 to any port 22 proto tcp
sudo ufw enable

# nginx
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    listen 443 ssl default_server;
    listen [::]:443 ssl default_server;
    ssl_reject_handshake on;
    return 444;
}

# nginx Authenticated Origin Pulls
ssl_client_certificate /etc/nginx/certs/origin-pull-ca.pem;
ssl_verify_client on;

# cloudflared
tunnel: TUNNEL_ID
credentials-file: /etc/cloudflared/TUNNEL_ID.json
ingress:
  - hostname: example.com
    service: http://localhost:8080
  - service: http_status:404

# curl
curl -sI --max-time 10 --resolve example.com:443:203.0.113.10 https://example.com/
